import {
  appendCharacterMenuTabs, markScrollable,
  decorateButton, humanize, sanitize, bracketize,
  show, hide, hideItemTooltip, rarityStyle, renderItemDetails,
  CHARACTER_SLOT_ORDER, installDetachableKeyHandler, pulseRow,
  UI, dispatchCharacterMenuTabCycle,
} from './overlayUtils.js';
import { applyAtlasIcon, resolveIconReference } from './atlasIcons.js';

/**
 * Resolve the primary equipment-row artwork without exposing unidentified gear.
 * @param {any} item
 * @param {string} slot
 * @returns {{ atlas: any, id: string, fallback: string, size: number }}
 */
export function resolveEquipmentIcon(item, slot) {
  const type = String(item?.type || '').toLowerCase();
  const isSpell = slot === 'brain' || type === 'spell';
  if (isSpell) {
    const id = String(item?.iconId || item?.spellId || item?.id || '').replace(/^spell:/, '');
    const iconRef = resolveIconReference({ ...item, iconAtlas: 'spells', iconId: id });
    return { atlas: iconRef.atlas, id: iconRef.id, fallback: String(item?.symbol || item?.glyph || '✦'), size: 30 };
  }

  const safeFallback = {
    potion: '◈', scroll: '▤', wand: '⚡', gem: '◇', ammo: '➶', food: '♨',
  }[type] || (item?.slot ? '◆' : '◇');
  const identified = item?.identified !== false;
  const iconRef = resolveIconReference(item);
  return {
    atlas: iconRef.atlas,
    id: iconRef.id,
    fallback: identified ? String(item?.glyph || safeFallback) : safeFallback,
    size: 30,
  };
}

/**
 * @param {HTMLDivElement & {_inner?:HTMLDivElement}} panel
 * @param {{ playerName?: string, stats?: Record<string, any>, activeEffects?: Array<any>, equippedBySlot?: Record<string, any> }} data
 */
export function renderCharacterSheet(panel, data) {
  const SEASON_COLORS = {
    spring: '#7ec87a',
    summer: '#f0c95a',
    autumn: '#d4834a',
    winter: '#8ab4d6',
  };
  const existingDetach = /** @type {any} */ (panel)._characterSheetDetach;
  if (typeof existingDetach === 'function') {
    try { existingDetach(); } catch (e) { console.debug('[overlay] character sheet detach failed:', e); }
  }

  const el = /** @type {HTMLDivElement} */ (/** @type {any} */ (panel)._inner);
  el.innerHTML = '';
  el.style.overflowX = 'hidden';
  el.style.width = 'min(760px, 92vw)';
  appendCharacterMenuTabs(el, 'character');

  const playerName = String(data?.playerName || 'Hero').trim() || 'Hero';
  const stats = data?.stats && typeof data.stats === 'object' ? data.stats : {};
  const equippedBySlot = data?.equippedBySlot && typeof data.equippedBySlot === 'object'
    ? data.equippedBySlot
    : {};
  const gearMechanics = [];
  const seenGearMechanics = new Set();
  for (const slot of CHARACTER_SLOT_ORDER) {
    const item = equippedBySlot?.[slot]?.item;
    const mechanics = Array.isArray(item?.mechanics) ? item.mechanics : [];
    for (const mechanic of mechanics) {
      const context = String(mechanic?.context || '').trim();
      const text = String(mechanic?.text || '').trim();
      if (!text || (context !== 'Equip' && context !== 'Enchant')) continue;
      const label = `${context} ${text}`;
      if (seenGearMechanics.has(label)) continue;
      seenGearMechanics.add(label);
      gearMechanics.push(label);
    }
  }
  const traits = Array.isArray(data?.traits) ? data.traits : [];
  const calendar = data?.calendar && typeof data.calendar === 'object' ? data.calendar : null;

  const title = document.createElement('div');
  title.textContent = `${playerName} \u00b7 Character Sheet`;
  title.style.fontWeight = 'bold';
  title.style.marginBottom = '8px';
  el.appendChild(title);

  if (calendar?.formatted) {
    const calendarCard = document.createElement('div');
    Object.assign(calendarCard.style, {
      marginBottom: '10px',
      padding: '8px 10px',
      border: UI.BORDER,
      borderRadius: UI.RADIUS,
      background: UI.DEFAULT_BG,
      fontSize: '13px',
      lineHeight: '1.4',
      color: SEASON_COLORS[String(calendar?.season || '')] || UI.TEXT,
      wordBreak: 'break-word',
    });
    const moonEmoji = String(calendar?.moonEmoji || '');
    const moonLabel = String(calendar?.moonLabel || '');
    calendarCard.textContent = `${moonEmoji ? `${moonEmoji} ` : ''}${String(calendar.formatted)}${moonLabel ? ` \u00b7 ${moonLabel}` : ''}`;
    el.appendChild(calendarCard);
  }

  const statCard = document.createElement('div');
  Object.assign(statCard.style, {
    padding: '8px',
    border: UI.BORDER,
    borderRadius: UI.RADIUS,
    background: UI.DEFAULT_BG,
    display: 'grid',
    gridTemplateColumns: 'repeat(2, minmax(0, 1fr))',
    gap: '6px 12px',
    fontSize: '13px',
  });
  el.appendChild(statCard);

  function deltaColor(value, baseline = 0) {
    const n = Number(value || 0);
    if (n > baseline) return '#64c87a';
    if (n < baseline) return '#e06a6a';
    return null;
  }

  // [label, value, color|null]  — null = default text color
  const statRows = [
    ['__header', 'Attributes'],
    ['Strength', `${Number(stats.strength || 0)}`, deltaColor(stats.strength)],
    ['Dexterity', `${Number(stats.dexterity || 0)}`, deltaColor(stats.dexterity)],
    ['Intelligence', `${Number(stats.intelligence || 0)}`, deltaColor(stats.intelligence)],
    ['Vitality', `${Number(stats.vitalityStat || 0)}`, deltaColor(stats.vitalityStat)],
    ['__header', 'Resources'],
    ['Health', `${Number(stats.hp || 0)}/${Number(stats.maxHp || 0)}`],
    ['Mana', `${Number(stats.mana || 0)}/${Number(stats.maxMana || 0)}  +${Number(stats.manaRegen || 0).toFixed(2)}/t`],
    ['Stamina', `${Number(stats.stamina || 0)}/${Number(stats.maxStamina || 0)}  +${Number(stats.staminaRegen || 0).toFixed(1)}/t`],
    ['__header', 'Capabilities'],
    ['Damage', `${Number(stats.damage || 0)}`, deltaColor(stats.damage)],
    ['Accuracy', `${Number(stats.accuracy || 0)}`, deltaColor(stats.accuracy)],
    ['Avoidance', `${Number(stats.avoidance || 0)}`, deltaColor(stats.avoidance)],
    ['Armor', `${Number(stats.armor || 0)}`, deltaColor(stats.armor)],
    ['Critical Strike', `${Number(stats.critChancePercent || 0).toFixed(1)}%`, deltaColor(stats.critChancePercent)],
    ['Spell Power', `${Number(stats.spellPower || 0)}`, deltaColor(stats.spellPower)],
    ['__header', 'Additional Details'],
    ['Damage Power', `${Number(stats.damagePower || 0)}`, deltaColor(stats.damagePower)],
    ['Mitigation', `${Number(stats.mitigation || 0)}`, deltaColor(stats.mitigation)],
    ['Luck', `${Number(stats.luck || 0)}`, deltaColor(stats.luck)],
    ['Crit Mult', `\u00d7${(2 + Number(stats.critMult || 0)).toFixed(1)}`, deltaColor(stats.critMult)],
    ['Dmg Bonus', `${Number(stats.damageFlatBonus || 0)}`, deltaColor(stats.damageFlatBonus)],
    ['Carry', `${Number(stats.carryWeight || 0).toFixed(1)}/${Number(stats.carryLimit || 0).toFixed(1)} kg · ${humanize(String(stats.carryState || 'unburdened'))}`],
    ['Max HP Bonus', `${Number(stats.maxHpDerived || 0)}`, deltaColor(stats.maxHpDerived)],
    ['Speed', `${Number(stats.speed || 1)}`, deltaColor(stats.speed, 1) === '#64c87a' ? '#e06a6a' : deltaColor(stats.speed, 1) === '#e06a6a' ? '#64c87a' : null],
    ['Gold', `${Number(stats.gold || 0)}`],
    ['Hunger', `${humanize(String(stats.hungerLevel || 'normal'))} (${Number(stats.hunger || 0)})`],
    ['Depth', `${Number(stats.depth || 0)}`],
    ['Turn', `${Number(stats.turn || 0)}`],
  ];
  for (const [label, value, color] of statRows) {
    if (label === '__header') {
      const header = document.createElement('div');
      header.textContent = value.toUpperCase();
      header.style.gridColumn = '1 / -1';
      header.style.marginTop = '8px';
      header.style.color = '#9ecbff';
      header.style.fontWeight = 'bold';
      statCard.appendChild(header);
      continue;
    }
    const row = document.createElement('div');
    const lbl = document.createElement('span');
    lbl.textContent = `${label}: `;
    const val = document.createElement('span');
    val.textContent = value;
    if (color) val.style.color = color;
    row.appendChild(lbl);
    row.appendChild(val);
    statCard.appendChild(row);
  }

  // Resistances — only show non-zero entries
  const resistRows = [
    ['Fire Resist', Number(stats.fireResist || 0)],
    ['Cold Resist', Number(stats.coldResist || 0)],
    ['Poison Resist', Number(stats.poisonResist || 0)],
    ['Acid Resist', Number(stats.acidResist || 0)],
    ['Rad Resist', Number(stats.radiationResist || 0)],
    ['Elec Resist', Number(stats.electricResist || 0)],
    ['Blunt Resist', Number(stats.bluntResist || 0)],
    ['Slash Resist', Number(stats.slashResist || 0)],
    ['Pierce Resist', Number(stats.pierceResist || 0)],
  ].filter(([, v]) => v !== 0);

  if (resistRows.length) {
    const resistHeader = document.createElement('div');
    resistHeader.textContent = 'Resistances';
    resistHeader.style.marginTop = '10px';
    resistHeader.style.fontWeight = 'bold';
    el.appendChild(resistHeader);

    const resistCard = document.createElement('div');
    Object.assign(resistCard.style, {
      marginTop: '6px',
      padding: '8px',
      border: UI.BORDER,
      borderRadius: UI.RADIUS,
      background: UI.DEFAULT_BG,
      display: 'grid',
      gridTemplateColumns: 'repeat(2, minmax(0, 1fr))',
      gap: '6px 12px',
      fontSize: '13px',
    });
    for (const [label, v] of resistRows) {
      const row = document.createElement('div');
      const lbl = document.createElement('span');
      lbl.textContent = `${label}: `;
      const val = document.createElement('span');
      val.textContent = `${v}`;
      val.style.color = deltaColor(v) || UI.TEXT;
      row.appendChild(lbl);
      row.appendChild(val);
      resistCard.appendChild(row);
    }
    el.appendChild(resistCard);
  }

  if (traits.length > 0) {
    const traitsTitle = document.createElement('div');
    traitsTitle.textContent = 'Traits';
    traitsTitle.style.marginTop = '10px';
    traitsTitle.style.fontWeight = 'bold';
    el.appendChild(traitsTitle);

    const traitsCard = document.createElement('div');
    Object.assign(traitsCard.style, {
      marginTop: '6px',
      padding: '8px',
      border: UI.BORDER,
      borderRadius: UI.RADIUS,
      background: UI.DEFAULT_BG,
      fontSize: '13px',
    });
    for (const t of traits) {
      const row = document.createElement('div');
      row.style.marginBottom = '4px';
      const lbl = document.createElement('span');
      lbl.textContent = String(t.label || t.key || '');
      lbl.style.color = '#ffd966';
      lbl.style.fontWeight = 'bold';
      const desc = document.createElement('span');
      desc.textContent = ` \u2014 ${String(t.description || '')}`;
      desc.style.opacity = '0.85';
      row.appendChild(lbl);
      row.appendChild(desc);
      traitsCard.appendChild(row);
    }
    el.appendChild(traitsCard);
  }

  const effectsTitle = document.createElement('div');
  effectsTitle.textContent = 'Gear Effects';
  effectsTitle.style.marginTop = '10px';
  effectsTitle.style.fontWeight = 'bold';
  el.appendChild(effectsTitle);

  const effects = document.createElement('div');
  Object.assign(effects.style, {
    marginTop: '6px',
    padding: '8px',
    border: UI.BORDER,
    borderRadius: UI.RADIUS,
    background: UI.DEFAULT_BG,
    maxHeight: '24vh',
    overflowY: 'auto',
    fontSize: '13px',
  });
  if (!gearMechanics.length) {
    const empty = document.createElement('div');
    empty.textContent = '(none)';

// display/ui/overlayUtils.js
// Shared utilities, panel management, tooltips, and standalone UI widgets.

import { getHighscoreVersionLabel, getHighscores } from '../../cloud/tombstones/client.js';
import { GAME_ICON_FONT_FAMILY, GAME_LOG_FONT_FAMILY, GAME_TEXT_FONT_FAMILY } from '../fonts.js';
import { CHARACTER_MENU_TAB_GLYPHS } from './iconGlyphs.js';
import { HUD_MARGIN, HUD_PANEL_STYLE } from './hudTheme.js';
import { applyAtlasIcon, resolveIconReference } from './atlasIcons.js';

export const PANEL_Z_BASE = 1200;
export let _panelZCounter = PANEL_Z_BASE;
export const UI_ROOT_Z_INDEX = 1000;
// Gameplay prompts must sit above HUD panels; modal dialogs use their own layer.
export const UI_TOOLTIP_Z_BASE = 1490;
export const UI_TOOLTIP_Z_FOCUS = 1500;
export const SPEECH_BUBBLE_LAYER_Z_INDEX = 2147483000;
export const DIALOG_LAYER_Z_INDEX = 2147483100;

/** Increment and return the panel z-index counter. */
export function bumpPanelZ() {
  _panelZCounter += 1;
  return _panelZCounter;
}

export const CHARACTER_SLOT_ORDER = Object.freeze([
  'brain',
  'weapon',
  'armor',
  'head',
  'neck',
  'belt',
  'gloves',
  'offhand',
  'ring1',
  'ring2',
  'legs',
  'feet',
  'ammo',
  'ranged',
]);
export const CHARACTER_MENU_TABS = Object.freeze([
  { key: 'character', icon: CHARACTER_MENU_TAB_GLYPHS.character, label: 'Character', eventName: 'ui:openCharacter' },
  { key: 'inventory', icon: CHARACTER_MENU_TAB_GLYPHS.inventory, label: 'Inventory', eventName: 'ui:openInventory' },
  { key: 'equipment', icon: CHARACTER_MENU_TAB_GLYPHS.equipment, label: 'Equipment', eventName: 'ui:openEquipment' },
  { key: 'quests', icon: CHARACTER_MENU_TAB_GLYPHS.quests, label: 'Quests', eventName: 'ui:openQuests' },
  { key: 'settings', icon: CHARACTER_MENU_TAB_GLYPHS.settings, label: 'Settings', eventName: 'ui:openSettings' },
]);
export const INTERACTION_POPUP_ARM_DELAY_MS = 250;

// --- _itemTooltip module state (mutable let) ---
let _itemTooltip = null;

export function getItemTooltip() {
  return _itemTooltip;
}

export function setItemTooltip(el) {
  _itemTooltip = el;
}

/**
 * @param {HTMLDivElement} host
 * @param {'character'|'inventory'|'equipment'|'settings'} activeKey
 */
export function appendCharacterMenuTabs(host, activeKey) {
  const tabs = document.createElement('div');
  Object.assign(tabs.style, {
    position: 'sticky',
    top: '0',
    zIndex: '3',
    display: 'grid',
    gridTemplateColumns: 'repeat(5, minmax(0, 1fr))',
    gap: '6px',
    marginBottom: '10px',
    paddingBottom: '8px',
    background: UX_THEME.panelBg,
    backdropFilter: 'blur(6px)',
  });

  for (const tab of CHARACTER_MENU_TABS) {
    const btn = document.createElement('button');
    decorateButton(btn);
    Object.assign(btn.style, {
      minHeight: '46px',
      padding: '6px 4px',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      gap: '3px',
      borderRadius: '8px',
    });
    const isActive = tab.key === activeKey;
    if (isActive) {
      btn.style.background = UX_THEME.surfaceSelected;
      btn.style.borderColor = UX_THEME.accentBorder;
      btn.style.color = UX_THEME.textStrong;
      btn.style.boxShadow = UX_THEME.accentGlow;
    }

    const icon = document.createElement('span');
    icon.textContent = tab.icon;
    icon.style.lineHeight = '1';
    icon.style.fontSize = '16px';
    icon.style.fontFamily = GAME_ICON_FONT_FAMILY;
    const label = document.createElement('span');
    label.textContent = tab.label;
    label.style.fontSize = '11px';
    label.style.lineHeight = '1';
    btn.title = tab.label;
    btn.setAttribute('aria-label', tab.label);
    if (isActive) btn.setAttribute('aria-current', 'page');
    btn.appendChild(icon);
    btn.appendChild(label);
    btn.addEventListener('click', () => {
      window.dispatchEvent(new CustomEvent(tab.eventName));
    });
    tabs.appendChild(btn);
  }

  host.appendChild(tabs);
}

/**
 * Cycle the shared character-menu tabs from keyboard handlers.
 * @param {string} activeKey
 * @param {boolean} reverse
 */
export function dispatchCharacterMenuTabCycle(activeKey, reverse = false) {
  const current = CHARACTER_MENU_TABS.findIndex((tab) => tab.key === activeKey);
  const start = current >= 0 ? current : 0;
  const dir = reverse ? -1 : 1;
  const next = (start + dir + CHARACTER_MENU_TABS.length) % CHARACTER_MENU_TABS.length;
  const tab = CHARACTER_MENU_TABS[next];
  if (tab?.eventName) window.dispatchEvent(new CustomEvent(tab.eventName));
}

/**
 * Mark an element as intentionally scrollable under global input lockdown.
 * @param {HTMLElement} el
 */
export function markScrollable(el) {
  if (!(el instanceof HTMLElement)) return;
  el.dataset.allowScroll = 'true';
  el.style.touchAction = 'pan-y';
  el.style.overscrollBehavior = 'contain';
}

/**
 * @param {any} item
 * @returns {string}
 */
export function quickPinKeyForItem(item) {
  const identity = String(item?.identity || item?.details?.identity || '');
  if (identity) return identity;
  const id = Number(item?.id || 0) | 0;
  return id > 0 ? `id:${id}` : '';
}

export function ensureRoot() {
  let root = document.getElementById('ui-root');
  if (!root) {
    root = document.createElement('div');
    root.id = 'ui-root';
    root.style.position = 'fixed';
    root.style.left = '0';
    root.style.top = '0';
    root.style.right = '0';
    root.style.bottom = '0';
    root.style.pointerEvents = 'none';
    root.style.zIndex = String(UI_ROOT_Z_INDEX);
    document.body.appendChild(root);
  }
  return root;
}

// --- Gesture debug overlay -------------------------------------------------
export function ensureGestureDebugLayer(root) {
  const canvas = document.createElement('canvas');
  canvas.id = 'gesture-debug-layer';

