    function openWithData(d) {
      const gearLines = (d?.gear || []).map(g => `  - ${g.slot}: ${g.name}`).join('\n') || '  (none)';
      const invLines = (d?.inv || []).map(i => `  - ${i}`).join('\n') || '  (none)';
      const effectsLine = (d?.effects || []).join(', ') || 'none';
      const s = d?.stats || {};
      const snapshot = d
